 27	/// Generate a Seatbelt (SBPL) profile string from sandbox config.
 28	pub(crate) async fn generate_seatbelt_profile(
 29	    config: &SandboxConfig,
 30	    initial_program: Option<&std::path::Path>,
 31	) -> String {
 32	    let mut rules = Vec::new();
 33	    rules.push("(version 1)".to_string());
 34	    rules.push("(allow default)".to_string());
 35	
 36	    // Filesystem write restrictions
 37	    if config.effective_deny_write() {
 38	        rules.push("(deny file-write*)".to_string());
 39	        if !config.deny_temp_write {
 40	            rules.push("(allow file-write* (subpath \"/tmp\"))".to_string());
 41	            rules.push("(allow file-write* (subpath \"/private/tmp\"))".to_string());
 42	        }
 43	        rules.push("(allow file-write* (subpath \"/dev\"))".to_string());
 44	        for path in &config.allow_write {
 45	            let path_str = sbpl_escape(&path.to_string_lossy());
 46	            rules.push(format!("(allow file-write* (subpath \"{path_str}\"))"));
 47	            rules.push(format!("(allow file-write* (literal \"{path_str}\"))"));
 48	        }
 49	    }
 50	
 51	    // Filesystem read restrictions
 52	    if config.effective_deny_read() {
 53	        rules.push("(deny file-read*)".to_string());
 54	        // Seatbelt requires data access to the root vnode for process startup and getcwd.
 55	        // This exposes names directly under `/`, but descendants still obey the read rules.
 56	        rules.push("(allow file-read-data (literal \"/\"))".to_string());
 57	        for path in SYSTEM_READ_PATHS {
 58	            rules.push(format!("(allow file-read* (subpath \"{path}\"))"));
 59	        }
 60	        let data_dir = &*crate::env::MISE_DATA_DIR;
 61	        let data_str = sbpl_escape(&data_dir.to_string_lossy());
 62	        rules.push(format!("(allow file-read* (subpath \"{data_str}\"))"));
 63	        for path in &config.allow_read {
 64	            let path_str = sbpl_escape(&path.to_string_lossy());
 65	            rules.push(format!("(allow file-read* (subpath \"{path_str}\"))"));
 66	            rules.push(format!("(allow file-read* (literal \"{path_str}\"))"));
 67	        }
 68	        // allow_write paths are implicitly readable — emit AFTER deny-read
 69	        for path in &config.allow_write {
 70	            let path_str = sbpl_escape(&path.to_string_lossy());
 71	            rules.push(format!("(allow file-read* (subpath \"{path_str}\"))"));
 72	            rules.push(format!("(allow file-read* (literal \"{path_str}\"))"));
 73	        }
 74	    }
 75	
 76	    // Network restrictions
 77	    if config.effective_deny_net() {
 78	        rules.push("(deny network*)".to_string());
205	        };
206	        let profile = generate_seatbelt_profile(&config, None).await;
207	        assert!(profile.contains("(deny file-read*)"));
208	        assert!(profile.contains("(allow file-read* (subpath \"/usr\"))"));
209	        assert!(profile.contains("(allow file-read* (subpath \"/System\"))"));
210	    }
