 61	        let data_str = sbpl_escape(&data_dir.to_string_lossy());
 62	        rules.push(format!("(allow file-read* (subpath \"{data_str}\"))"));
 63	        for path in &config.allow_read {
 64	            let path_str = sbpl_escape(&path.to_string_lossy());
 65	            rules.push(format!("(allow file-read* (subpath \"{path_str}\"))"));
 66	            rules.push(format!("(allow file-read* (literal \"{path_str}\"))"));
 67	        }
 68	        // allow_write paths are implicitly readable — emit AFTER deny-read
 69	        for path in &config.allow_write {
